getData() {
  const busCode = this.effectiveBusCode
  const dataId = this.getId()
  if (!busCode || dataId == null || dataId === '') {
    this.flowList = []
    this.stepList = []
    return Promise.resolve()
  }
  return flowRecordCity({
    busCode,
    dataId
  }).then((res) => {
    if (res.code != 200) {
      this.flowList = []
      this.stepList = []
      return
    }
    const list = this.normalizeAcLogFlowList(res.data)
    this.flowList = list
    this.stepList = this.buildStepListFromAcLog(list)
    this.activeStep = Math.max(this.stepList.length - 1, 0)
  })
},
normalizeAcLogFlowList(payload) {
  if (Array.isArray(payload)) return payload
  if (payload && Array.isArray(payload.flowList)) return payload.flowList
  if (payload && Array.isArray(payload.rows)) return payload.rows
  if (payload && Array.isArray(payload.list)) return payload.list
  return []
},
buildStepListFromAcLog(list) {
  return (list || []).map((item) => ({
    taskName: item.nodeName || item.taskName || ''
  }))
},
resolveStatusType(item) {
  if (!item) return undefined
  const flowableType = item.comment && item.comment.type
  if (flowableType !== undefined && flowableType !== null && flowableType !== '') {
    return flowableType
  }
  const optionResult = item.optionResult
  if (optionResult === 0 || optionResult === '0') return 1
  if (optionResult === 1 || optionResult === '1') return 2
  return undefined
}

